    for(const string& name:names){
        auto c=closes(history.at(name));
        if(c.size()<61)return {};
        cl[name]=c;
        data[name]=tail(returns(c),40);
    }
    auto m=data[names[2]];
    double mm=avg(m),vm=0;
    for(double z:m)vm+=(z-mm)*(z-mm);
    if(vm<1e-12)return {};
