    auto a=cl[names[0]],b=cl[names[1]];
    if(a.back()/a[a.size()-21]<=b.back()/b[b.size()-21])return {};
    return {{names[0],beta[1]/(beta[0]+beta[1])},{names[1],-beta[0]/(beta[0]+beta[1])}};
}

